# SPDX-License-Identifier: Apache-2.0
"""Eager terminal patterns and directed phase propagation over shared syntax."""
import ast,re
from data_layer_six.common import A,O,K,P,E,S,q,literals
from data_layer_eight.contracts import constants
from data_layer_eight.model import stages as model
from data_layer_eight.relations import clause


def candidate(source,policy):
    v=constants(source/'scripts/lint_eager_resolve.py')
    vals=lambda *names:literals(set().union(*(v[n] for n in names)))
    prefixes=lambda name:q('^(?:'+'|'.join(map(re.escape,sorted(v[name])))+')')
    external=[line.strip() for line in (source/'scripts/allowlists/lint_eager_resolve_external_io_boundaries.txt').read_text().splitlines() if line.strip() and not line.startswith('#')]
    p=policy('eager_resolve',['impl/**/*.py','api/**/*.py','l[0-9][0-9][0-9][0-9]_*/**/*.py'])
    p['clauses'].append({'id':'entry','define':{'options':{'oracleAnalyzer':{'type':'boolean','default':False},'entryPoint':{'type':'string','default':'_scan_source'},'externalIoBoundaries':{'type':'array','items':'string','default':external}}}})
    stages=[*model(),
      S('approved_external',{'$option':'externalIoBoundaries','escape':'sql','map':' UNION ALL SELECT {} symbol','join':'','template':"SELECT '' symbol WHERE 0{}"},('symbol',)),
      S('function_info',"SELECT f.*,replace(substr(f.__path,1,length(f.__path)-3),'/','.')||'.'||f.qualname symbol,rx_matches(f.__path,"+prefixes('SERVERPLAN_LAZY_REL_PREFIXES')+") serverplan,own.cls function_cls FROM declaration_contexts f JOIN ownership own ON own.__path=f.__path AND own.id=f.id WHERE f.kind='function_definition'",('__path','id')),
      S('nested_regions',"SELECT __path,__start,__end,kind FROM nodes WHERE kind IN ('lambda','class_definition')",('__path','kind','__start','__end')),
      S('body_calls',"SELECT c.*,f.id fn,f.symbol,f.serverplan FROM calls c JOIN ownership o ON o.__path=c.__path AND o.id=c.id JOIN function_info f ON f.__path=o.__path AND f.id=o.fn AND o.cls IS f.function_cls WHERE c.__start>=f.body_start AND c.__end<=f.body_end AND NOT EXISTS(SELECT 1 FROM nested_regions l WHERE l.__path=c.__path AND l.kind='lambda' AND l.__start<c.__start AND l.__end>=c.__end)",('__path','fn'),('__path','id')),
      S('body_attributes',"SELECT a.*,f.id fn,f.serverplan FROM attributes a JOIN ownership o ON o.__path=a.__path AND o.id=a.id JOIN function_info f ON f.__path=o.__path AND f.id=o.fn WHERE a.__start>=f.body_start AND a.__end<=f.body_end AND NOT EXISTS(SELECT 1 FROM nested_regions l WHERE l.__path=a.__path AND l.kind IN ('lambda','class_definition') AND l.__start>f.body_start AND l.__start<a.__start AND l.__end>=a.__end)",('__path','fn')),
      S('empty_calls',"SELECT c.* FROM body_calls c WHERE NOT EXISTS(SELECT 1 FROM nodes arg WHERE arg.__path=c.__path AND arg.parent=c.arguments_kind||':'||c.arguments_start||':'||c.arguments_end AND arg.kind!='comment')",('__path','id')),
      S('eager_edges',"SELECT DISTINCT c.__path,c.fn caller,t.id target FROM body_calls c JOIN function_info owner ON owner.__path=c.__path AND owner.id=c.fn JOIN function_info t ON t.__path=c.__path AND t.name=c.callee JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver WHERE c.callee_kind='attribute' AND receiver.kind='identifier' AND receiver.text='self' AND t.lexical_parent=owner.lexical_parent UNION SELECT c.__path,c.fn,t.id FROM body_calls c JOIN function_info t ON t.__path=c.__path AND t.name=c.callee AND t.lexical_parent IS NULL WHERE c.callee_kind='identifier'",('__path','caller'),('__path','target')),
      S('phases',"WITH RECURSIVE phase(__path,fn,name) AS (SELECT __path,id,name FROM function_info WHERE name IN ('preprocess','lower','compile') UNION SELECT e.__path,e.target,p.name FROM phase p JOIN eager_edges e ON e.__path=p.__path AND e.caller=p.fn) SELECT * FROM phase",('__path','fn')),
      S('legacy_aliases',"WITH RECURSIVE alias(__path,name) AS (SELECT n.__path,h.name FROM nodes n CROSS JOIN ("+' UNION ALL '.join('SELECT '+q(n)+' name' for n in sorted(v['LEGACY_DELEGATE_DECORATORS']))+") h WHERE n.kind='module' UNION SELECT n.__path,n.alias_source FROM nodes n JOIN nodes parent ON parent.__path=n.__path AND parent.id=n.parent WHERE n.kind='aliased_import' AND parent.kind='import_from_statement' AND parent.module_name_source='l2050_transaction.legacy_wrappers' AND n.name_source IN "+vals('LEGACY_DELEGATE_DECORATORS')+" UNION SELECT a.__path,b.name FROM assignments a JOIN bound_names b ON b.__path=a.__path AND b.assignment=a.id JOIN alias old ON old.__path=a.__path AND old.name=a.expr_text WHERE a.fn IS NULL AND a.expr_kind='identifier') SELECT * FROM alias",('__path','name')),
      S('legacy_functions',"SELECT f.__path,f.id FROM function_info f WHERE EXISTS(SELECT 1 FROM decorator_names d JOIN legacy_aliases a ON a.__path=d.__path AND a.name=d.name WHERE d.__path=f.__path AND d.fn=f.id) OR EXISTS(SELECT 1 FROM body_calls c WHERE c.__path=f.__path AND c.fn=f.id AND c.full_callee IN ('_legacy_delegate_stub','_legacy_delegate_stub_async','_resolve_legacy_result_sync','_resolve_legacy_result_async','run_in_legacy_execution_boundary','run_in_legacy_execution_boundary_async'))",('__path','id')),
      S('indirect_targets',"""SELECT c.__path,c.id expression,c.fn,t.id target FROM body_calls c JOIN arguments first ON first.__path=c.__path AND first.call=c.id AND first.position=0 JOIN arguments second ON second.__path=c.__path AND second.call=c.id AND second.position=1 JOIN strings s ON s.__path=second.__path AND s.__start=second.__start JOIN function_info owner ON owner.__path=c.__path AND owner.id=c.fn JOIN function_info t ON t.__path=c.__path AND t.name=s.value AND t.lexical_parent=owner.lexical_parent WHERE c.callee_kind='identifier' AND c.callee='getattr' AND first.kind='identifier' AND first.text='self'
        UNION SELECT c.__path,c.id,c.fn,t.id FROM body_calls c JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver JOIN arguments first ON first.__path=c.__path AND first.call=c.id AND first.position=0 JOIN strings s ON s.__path=first.__path AND s.__start=first.__start JOIN function_info owner ON owner.__path=c.__path AND owner.id=c.fn JOIN function_info t ON t.__path=c.__path AND t.name=s.value AND t.lexical_parent=owner.lexical_parent WHERE c.callee='__getattribute__' AND receiver.kind='identifier' AND receiver.text='self'
        UNION SELECT n.__path,n.id,o.fn,t.id FROM nodes n JOIN nodes value ON value.__path=n.__path AND value.parent=n.id AND value.ordinal=0 JOIN calls c ON c.__path=value.__path AND c.id=value.id AND c.callee_kind='identifier' AND c.callee='globals' JOIN nodes sub ON sub.__path=n.__path AND sub.parent=n.id AND sub.ordinal=1 JOIN strings s ON s.__path=sub.__path AND s.__start=sub.__start JOIN ownership o ON o.__path=n.__path AND o.id=n.id JOIN function_info t ON t.__path=n.__path AND t.name=s.value AND t.lexical_parent IS NULL WHERE n.kind='subscript'""",('__path','expression')),
      S('legacy_calls',"SELECT c.__path,c.fn,t.id,t.name FROM body_calls c JOIN eager_edges e ON e.__path=c.__path AND e.caller=c.fn JOIN function_info t ON t.__path=e.__path AND t.id=e.target AND t.name=c.callee JOIN legacy_functions legacy ON legacy.__path=t.__path AND legacy.id=t.id WHERE t.id!=c.fn UNION SELECT c.__path,c.fn,t.id,t.name FROM body_calls c JOIN indirect_targets indirect ON indirect.__path=c.__path AND indirect.expression=c.callee_id JOIN function_info t ON t.__path=indirect.__path AND t.id=indirect.target JOIN legacy_functions legacy ON legacy.__path=t.__path AND legacy.id=t.id WHERE t.id!=c.fn UNION SELECT c.__path,c.fn,t.id,t.name FROM body_calls c JOIN assignments a ON a.__path=c.__path AND a.fn=c.fn AND a.target_kind='identifier' AND a.target_text=c.callee JOIN indirect_targets indirect ON indirect.__path=a.__path AND indirect.expression=a.value JOIN function_info t ON t.__path=indirect.__path AND t.id=indirect.target JOIN legacy_functions legacy ON legacy.__path=t.__path AND legacy.id=t.id WHERE c.callee_kind='identifier' AND t.id!=c.fn",('__path','fn')),
      S('typed_parameters',"""WITH RECURSIVE annotation(__path,fn,name,id) AS (
        SELECT __path,fn,name,annotation FROM parameters WHERE annotation IS NOT NULL
        UNION ALL SELECT a.__path,a.fn,a.name,n.id FROM annotation a JOIN nodes n ON n.__path=a.__path AND n.parent=a.id)
        SELECT DISTINCT a.__path,a.fn,a.name,n.text type FROM annotation a JOIN nodes n ON n.__path=a.__path AND n.id=a.id WHERE n.kind='identifier'""",('__path','fn','name','type')),
      S('scope_names',"SELECT __path,fn,name FROM parameters WHERE name GLOB '*scope' UNION SELECT o.__path,o.fn,target.text FROM nodes pattern JOIN nodes value ON value.__path=pattern.__path AND value.parent=pattern.id AND value.ordinal=0 JOIN calls c ON c.__path=value.__path AND c.id=value.id JOIN nodes alias ON alias.__path=pattern.__path AND alias.parent=pattern.id AND alias.kind='as_pattern_target' JOIN nodes target ON target.__path=alias.__path AND target.parent=alias.id AND target.kind='identifier' JOIN ownership o ON o.__path=pattern.__path AND o.id=pattern.id WHERE pattern.kind='as_pattern' AND c.callee IN ('open_read_plan','open_write_plan')",('__path','fn','name')),
      S('scope_calls',"SELECT c.__path,c.id FROM empty_calls c LEFT JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver LEFT JOIN calls cast_call ON cast_call.__path=receiver.__path AND cast_call.id=receiver.id AND cast_call.callee='cast' LEFT JOIN arguments second ON second.__path=cast_call.__path AND second.call=cast_call.id AND second.position=1 AND second.kind='identifier' JOIN scope_names s ON s.__path=c.__path AND s.fn=c.fn AND s.name=coalesce(second.text,CASE WHEN receiver.kind='identifier' THEN receiver.text END) WHERE c.callee_kind='attribute' AND c.callee='execute'",('__path','id')),
      S('lazy_names',"""WITH RECURSIVE lazy(__path,fn,name,since) AS (
        SELECT __path,fn,name,-1 FROM typed_parameters WHERE type='LazyResult'
        UNION SELECT a.__path,a.fn,a.target_text,a.__start FROM assignments a JOIN calls c ON c.__path=a.__path AND c.id=a.value WHERE a.target_kind='identifier' AND c.callee GLOB '*_lazy'
        UNION SELECT a.__path,a.fn,a.target_text,a.__start FROM assignments a JOIN nodes annotation ON annotation.__path=a.__path AND annotation.id=a.type_kind||':'||a.type_start||':'||a.type_end JOIN nodes n ON n.__path=a.__path AND n.__start>=annotation.__start AND n.__end<=annotation.__end WHERE a.target_kind='identifier' AND n.kind='identifier' AND n.text='LazyResult'
        UNION SELECT a.__path,a.fn,a.target_text,a.__start FROM assignments a JOIN lazy old ON old.__path=a.__path AND old.fn=a.fn AND old.name=a.expr_text AND old.since<a.__start WHERE a.target_kind='identifier' AND a.expr_kind='identifier') SELECT * FROM lazy""",('__path','fn','name')),
      S('lazy_expressions',"""WITH RECURSIVE lazy(__path,fn,id) AS (
        SELECT n.__path,o.fn,n.id FROM nodes n JOIN ownership o ON o.__path=n.__path AND o.id=n.id WHERE n.kind='identifier' AND EXISTS(SELECT 1 FROM lazy_names l WHERE l.__path=n.__path AND l.fn=o.fn AND l.name=n.text)
        UNION SELECT c.__path,c.fn,c.id FROM body_calls c WHERE c.callee GLOB '*_lazy'
        UNION SELECT c.__path,c.fn,c.id FROM body_calls c JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=1 JOIN lazy old ON old.__path=a.__path AND old.fn=c.fn AND old.id=a.id WHERE c.callee='cast') SELECT * FROM lazy""",('__path','fn','id')),
      S('sql_expressions',"""WITH RECURSIVE sql_value(__path,fn,id) AS (
        SELECT c.__path,c.fn,c.id FROM body_calls c WHERE c.callee IN """+vals('SQL_DERIVED_RESOLVER_NAMES')+" OR rx_matches(c.callee,"+prefixes('SQL_DERIVED_SOURCE_PREFIXES')+") AND c.callee NOT GLOB '*_lazy'\n UNION SELECT n.__path,o.fn,n.id FROM sql_value old JOIN assignments a ON a.__path=old.__path AND a.fn=old.fn AND a.value=old.id JOIN nodes n ON n.__path=a.__path AND n.kind='identifier' AND n.text=a.target_text AND n.__start>a.__start JOIN ownership o ON o.__path=n.__path AND o.id=n.id AND o.fn=a.fn WHERE a.target_kind='identifier'\n UNION SELECT n.__path,old.fn,n.id FROM sql_value old JOIN nodes child ON child.__path=old.__path AND child.id=old.id JOIN nodes n ON n.__path=child.__path AND n.id=child.parent WHERE n.kind IN ('attribute','await')) SELECT * FROM sql_value",('__path','fn','id')),
    ]
    # Every event carries a source node, a pattern suffix, and the applicable passes.
    rows=[]
    def event(sql):rows.append(sql)
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'*.'||c.callee||'()' pattern,1 dirty,1 transitive FROM empty_calls c WHERE c.callee_kind='attribute' AND c.callee IN ('resolve','resolve_async','result')")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,c.callee||'()',1,1 FROM body_calls c WHERE c.callee_kind='identifier' AND c.callee IN "+vals('PREPROCESS_EAGER_HELPERS','FORBIDDEN_EAGER_HELPERS'))
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,CASE WHEN c.callee_kind='attribute' THEN '*.' ELSE '' END||c.callee||'()',1,1 FROM body_calls c WHERE c.callee IN "+vals('FORBIDDEN_TRANSITIVE_HELPERS'))
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,CASE WHEN c.callee_kind='attribute' THEN '*.' ELSE '' END||c.callee||'()',1,0 FROM body_calls c WHERE c.callee_kind='identifier' AND c.callee IN "+vals('FORBIDDEN_DIRTY_PHASE_HELPERS')+" OR c.serverplan AND rx_matches(c.callee,"+prefixes('FORBIDDEN_TRANSITIVE_HELPER_PREFIXES')+")")
    event("SELECT a.__path,a.fn,a.id,a.__start,a.__end,'*.'||a.attr,1,CASE WHEN a.attr IN "+vals('FORBIDDEN_DIRTY_PHASE_ATTRS')+" OR a.attr='__dict__' THEN 0 ELSE 1 END FROM body_attributes a WHERE a.attr IN "+vals('FORBIDDEN_PLANNING_STATE_ATTRS','FORBIDDEN_LITERAL_PROBE_ATTRS','FORBIDDEN_DIRTY_PHASE_ATTRS')+" AND (a.attr!='__dict__' OR a.serverplan) AND NOT (a.attr='deleted_state_value' AND EXISTS(SELECT 1 FROM assignments x JOIN nodes annotation ON annotation.__path=x.__path AND annotation.id=x.type_kind||':'||x.type_start||':'||x.type_end JOIN nodes n ON n.__path=x.__path AND n.__start>=annotation.__start AND n.__end<=annotation.__end WHERE x.__path=a.__path AND x.fn=a.fn AND x.target_text=a.object_text AND n.kind='identifier' AND n.text='PlanningServerValueShape'))")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,CASE WHEN c.callee_kind='attribute' THEN '*.' ELSE '' END||c.callee||'('||s.value||')',1,CASE WHEN s.value IN "+vals('FORBIDDEN_DIRTY_PHASE_ATTRS')+" OR s.value='__dict__' OR c.callee='getattr_static' THEN 0 ELSE 1 END FROM body_calls c JOIN arguments a ON a.__path=c.__path AND a.call=c.id JOIN strings s ON s.__path=a.__path AND s.__start=a.__start WHERE s.value IN "+vals('FORBIDDEN_PLANNING_STATE_ATTRS','FORBIDDEN_LITERAL_PROBE_ATTRS','FORBIDDEN_DIRTY_PHASE_ATTRS')+" AND (s.value!='__dict__' OR c.serverplan) AND (c.callee_kind='identifier' AND c.callee IN ('getattr','hasattr') AND a.position=1 OR c.callee_kind='attribute' AND c.callee='getattr_static' AND a.position=1 AND c.serverplan OR c.callee_kind='attribute' AND c.callee='__getattribute__' AND a.position=(SELECT max(position) FROM arguments last WHERE last.__path=c.__path AND last.call=c.id))")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'*.'||bound.attr||'<bound>',1,1 FROM body_calls c JOIN (SELECT __path,call,value FROM keywords UNION ALL SELECT __path,call,id FROM arguments) arg ON arg.__path=c.__path AND arg.call=c.id JOIN attributes bound ON bound.__path=arg.__path AND bound.id=arg.value WHERE bound.attr IN ('resolve','resolve_async') UNION ALL SELECT a.__path,a.fn,a.id,a.__start,a.__end,'*.'||bound.attr||'<bound>',1,1 FROM assignments a JOIN attributes bound ON bound.__path=a.__path AND bound.id=a.value WHERE bound.attr IN ('resolve','resolve_async')")
    event("SELECT __path,fn,id,0,0,'legacy-boundary-call:'||name||'()',0,1 FROM legacy_calls")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'plan-scope:*.execute()',0,1 FROM body_calls c JOIN scope_calls s ON s.__path=c.__path AND s.id=c.id")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'non-lazy-call:*.'||c.callee||'()',0,1 FROM body_calls c JOIN expression_roots root ON root.__path=c.__path AND root.expression=c.receiver WHERE c.callee_kind='attribute' AND c.callee IN "+vals('NON_LAZY_DB_TERMINAL_ATTRS')+" AND NOT EXISTS(SELECT 1 FROM scope_calls s WHERE s.__path=c.__path AND s.id=c.id) AND (EXISTS(SELECT 1 FROM parameters p WHERE p.__path=c.__path AND p.fn=c.fn AND p.name=root.name AND (p.name IN ('txn','transaction','read_txn','write_txn') OR p.name GLOB '*_txn')) OR EXISTS(SELECT 1 FROM typed_parameters p WHERE p.__path=c.__path AND p.fn=c.fn AND p.name=root.name AND p.type='Transaction'))")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'callback-terminal:*.'||c.callee||'()',0,1 FROM empty_calls c JOIN function_info f ON f.__path=c.__path AND f.id=c.fn JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver WHERE instr(f.name,'callback')>0 AND c.callee_kind='attribute' AND c.callee IN "+vals('CALLBACK_LAZY_ROW_TERMINAL_ATTRS')+" AND receiver.kind='identifier' AND receiver.text IN "+vals('CALLBACK_LAZY_ROW_TERMINAL_RECEIVERS'))
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'lazy-python:'||c.callee||'(lazy)',0,1 FROM body_calls c JOIN arguments a ON a.__path=c.__path AND a.call=c.id AND a.position=0 JOIN lazy_expressions l ON l.__path=a.__path AND l.fn=c.fn AND l.id=a.id WHERE c.callee_kind='identifier' AND c.callee IN "+vals('LAZY_PYTHON_MATERIALIZER_FUNCS'))
    event("SELECT n.__path,l.fn,n.id,n.__start,n.__end,'lazy-python:lazy[...]',0,1 FROM nodes n JOIN nodes child ON child.__path=n.__path AND child.parent=n.id AND child.ordinal=0 JOIN lazy_expressions l ON l.__path=child.__path AND l.id=child.id WHERE n.kind='subscript' UNION SELECT n.__path,l.fn,n.id,n.__start,n.__end,'lazy-python:for lazy',0,1 FROM nodes n JOIN lazy_expressions l ON l.__path=n.__path AND l.id=n.right_kind||':'||n.right_start||':'||n.right_end WHERE n.kind IN ('for_statement','for_in_clause') UNION SELECT n.__path,l.fn,n.id,n.__start,n.__end,'lazy-python:if lazy',0,1 FROM nodes n JOIN nodes cond ON cond.__path=n.__path AND cond.id=n.condition_kind||':'||n.condition_start||':'||n.condition_end JOIN lazy_expressions l ON l.__path=cond.__path AND l.id=cond.id WHERE n.kind IN ('if_statement','conditional_expression') AND cond.kind='identifier'")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'sql-derived-python:permission-check',0,1 FROM body_calls c WHERE c.callee IN "+vals('PYTHON_PERMISSION_CHECK_NAMES')+" AND EXISTS(SELECT 1 FROM sql_expressions s JOIN nodes n ON n.__path=s.__path AND n.id=s.id WHERE s.__path=c.__path AND s.fn=c.fn AND n.__start>=c.arguments_start AND n.__end<=c.arguments_end)")
    event("SELECT c.__path,c.fn,c.id,c.__start,c.__end,'permission-sql:direct-permission-expression',0,1 FROM body_calls c JOIN arguments first ON first.__path=c.__path AND first.call=c.id AND first.position=0 JOIN calls field ON field.__path=first.__path AND field.id=first.id AND field.callee='field' JOIN arguments arg ON arg.__path=field.__path AND arg.call=field.id AND arg.position=0 JOIN attributes attr ON attr.__path=arg.__path AND attr.id=arg.id WHERE c.callee='IN' AND attr.attr IN "+vals('PERMISSION_FIELD_NAME_MARKERS')+" AND c.__path NOT GLOB 'l4000_permissions/*' AND c.__path NOT GLOB '*permission_scheme.py'")
    stages.extend([
      S('raw_patterns',' UNION ALL '.join(rows),('__path','fn')),
      S('meaningful_statements',"SELECT f.__path,f.id fn,n.id,n.__start,n.kind FROM function_info f JOIN nodes n ON n.__path=f.__path AND n.parent=f.body_kind||':'||f.body_start||':'||f.body_end WHERE n.kind!='comment' AND NOT (n.kind='expression_statement' AND n.ordinal=0 AND EXISTS(SELECT 1 FROM nodes v WHERE v.__path=n.__path AND v.parent=n.id AND v.kind IN ('string','concatenated_string')))" ,('__path','fn')),
      S('canonical_wrappers',"""SELECT f.__path,f.id FROM function_info f JOIN meaningful_statements s ON s.__path=f.__path AND s.fn=f.id JOIN nodes stmt ON stmt.__path=s.__path AND stmt.id=s.id JOIN nodes value ON value.__path=stmt.__path AND value.parent=stmt.id AND value.ordinal=0 LEFT JOIN nodes awaited ON awaited.__path=value.__path AND awaited.parent=value.id AND value.kind='await' JOIN calls c ON c.__path=value.__path AND c.id=CASE WHEN rx_matches(f.text,'^async\\b') THEN awaited.id ELSE value.id END
        JOIN (SELECT __path,call,id value FROM arguments WHERE position=2 UNION ALL SELECT __path,call,value FROM keywords WHERE name='build_lazy') build ON build.__path=c.__path AND build.call=c.id JOIN nodes lambda ON lambda.__path=build.__path AND lambda.id=build.value AND lambda.kind='lambda' JOIN calls lazy ON lazy.__path=lambda.__path AND lazy.id=lambda.body_kind||':'||lambda.body_start||':'||lambda.body_end
        WHERE s.kind IN ('return_statement','expression_statement') AND c.callee_kind='identifier' AND c.callee=CASE WHEN rx_matches(f.text,'^async\\b') THEN '_resolve_legacy_result_async' ELSE '_resolve_legacy_result_sync' END AND lazy.callee GLOB '*_lazy' AND NOT rx_matches(lazy.full_callee,'[()]') AND (SELECT count(*) FROM meaningful_statements other WHERE other.__path=f.__path AND other.fn=f.id)=1""",('__path','id')),
      S('seed_patterns',"SELECT DISTINCT r.__path,r.fn,'transitive:'||r.pattern issue FROM raw_patterns r JOIN function_info f ON f.__path=r.__path AND f.id=r.fn WHERE r.transitive AND NOT (r.pattern IN ('_resolve_legacy_result_sync()','_resolve_legacy_result_async()') AND EXISTS(SELECT 1 FROM canonical_wrappers w WHERE w.__path=r.__path AND w.id=r.fn)) AND NOT (f.symbol GLOB 'l2050_transaction.legacy_wrappers.*' OR f.symbol='l2070_batching.server_ref.deleted_planning_value_helper') AND NOT (r.pattern='*.resolve()' AND rx_matches(f.symbol,"+prefixes('NON_LAZY_RESOLVE_SYMBOL_PREFIXES')+")) AND NOT (r.pattern='*.result()' AND f.symbol IN "+vals('NON_LAZY_RESULT_SYMBOLS')+") AND NOT (f.symbol IN (SELECT symbol FROM approved_external) AND EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=f.__path AND d.fn=f.id AND d.name IN "+vals('EXTERNAL_IO_BOUNDARY_DECORATORS')+") AND (r.pattern GLOB 'non-lazy-call:*' OR r.pattern IN ('*.resolve()','*.resolve_async()','*.result()')))",('__path','fn')),
      S('transitive_patterns',"WITH RECURSIVE dirty(__path,fn,issue) AS (SELECT * FROM seed_patterns UNION SELECT e.__path,e.caller,d.issue FROM dirty d JOIN eager_edges e ON e.__path=d.__path AND e.target=d.fn JOIN function_info f ON f.__path=e.__path AND f.id=e.caller WHERE f.symbol NOT GLOB 'l2050_transaction.legacy_wrappers.*' AND f.symbol!='l2070_batching.server_ref.deleted_planning_value_helper') SELECT f.__path,f.__start,f.__end,d.issue,f.id||':'||d.issue identity FROM dirty d JOIN function_info f ON f.__path=d.__path AND f.id=d.fn"),
      S('phase_patterns',"SELECT r.__path,min(r.__start) __start,min(r.__end) __end,p.name||':'||r.pattern issue,r.fn||':'||p.name||':'||r.pattern identity FROM raw_patterns r JOIN phases p ON p.__path=r.__path AND p.fn=r.fn WHERE r.dirty AND r.pattern NOT GLOB '_resolve_legacy_result_*' GROUP BY r.__path,r.fn,p.name,r.pattern"),
      S('external_definitions',"SELECT f.__path,f.__start,f.__end,'external-io-boundary:'||f.name||'()' issue,f.id identity FROM function_info f WHERE EXISTS(SELECT 1 FROM decorator_names d WHERE d.__path=f.__path AND d.fn=f.id AND d.name IN "+vals('EXTERNAL_IO_BOUNDARY_DECORATORS')+")"),
      S('preprocess_patterns',"SELECT c.__path,c.__start,c.__end,'preprocess:'||CASE WHEN c.callee_kind='identifier' THEN c.callee||'()' WHEN receiver.text='resolved' AND c.callee IN ('get','peek','resolve_server_ref') THEN 'resolved.'||c.callee||'()' ELSE '*.resolve(resolved)' END issue,c.id identity FROM body_calls c JOIN function_info f ON f.__path=c.__path AND f.id=c.fn LEFT JOIN nodes receiver ON receiver.__path=c.__path AND receiver.id=c.receiver WHERE f.name='preprocess' AND (c.callee_kind='identifier' AND c.callee IN "+vals('PREPROCESS_EAGER_HELPERS')+" OR c.callee_kind='attribute' AND EXISTS(SELECT 1 FROM parameters p WHERE p.__path=c.__path AND p.fn=c.fn AND p.name='resolved' AND p.position>=1 AND p.kind!='typed_default_parameter') AND (receiver.kind='identifier' AND receiver.text='resolved' AND c.callee IN ('get','peek','resolve_server_ref') OR c.callee='resolve' AND EXISTS(SELECT 1 FROM arguments a WHERE a.__path=c.__path AND a.call=c.id AND a.kind='identifier' AND a.text='resolved')))")])
    transitive=next(stage for stage in stages if stage['name']=='transitive_patterns')
    transitive['query']+=" WHERE NOT(f.__path IN ('l2055_lazy_result/lazy_result.py','l2055_lazy_result/lazy_seq.py') AND (f.symbol IN "+vals('LOCKED_PUBLIC_LAZY_FACADE_SYMBOLS')+" OR rx_matches(f.symbol,"+prefixes('LOCKED_PUBLIC_LAZY_FACADE_SYMBOL_PREFIXES')+"))) AND NOT(f.__path='l2070_batching/server_ref.py' AND d.issue IN "+vals('SERVER_REF_CORE_SLOT_PATTERN_NAMES')+")"
    transitive['query']+=" AND NOT(f.__path='l2070_batching/step.py' AND d.issue='transitive:*._ref_id' AND f.symbol GLOB 'l2070_batching.step.StepRef.*')"
    transitive['query']+=" AND NOT rx_matches(f.__path,'^conform/|(?:^|/)(?:tests|test_[^/]*)/') AND NOT rx_matches(f.__path,'(?:^|/)test_[^/]*$')"
    patterns=[]
    for assignment in ast.parse((source/'scripts/lint_eager_resolve.py').read_text()).body:
        if isinstance(assignment,ast.AnnAssign) and isinstance(assignment.target,ast.Name) and assignment.target.id=='EAGER_PATTERNS':
            patterns=[(ast.literal_eval(item.elts[0].args[0]),ast.literal_eval(item.elts[1])) for item in assignment.value.elts]
    raw=E(A(K('module'),{'regex':r'(?m)^(?<LINE>[^\n]*(?:'+ '|'.join(pattern for pattern,_ in patterns)+r')[^\n]*)$'}),{'line':'capture.LINE.startLine','text':'capture.LINE'},each='LINE',anchor='capture.LINE')
    stages.extend([
      S('line_patterns',' UNION ALL '.join('SELECT '+q(pattern)+' pattern,'+q(name)+' issue' for pattern,name in patterns)),
      S('direct_sites',"SELECT l.*,p.issue,coalesce((SELECT f.symbol FROM function_info f WHERE f.__path=l.__path AND f.line<=l.line AND l.line<=f.line+length(f.text)-length(replace(f.text,char(10),'')) ORDER BY length(f.qualname)-length(replace(f.qualname,'.','')) DESC,length(f.text) LIMIT 1),replace(substr(l.__path,1,length(l.__path)-3),'/','.')||'::<module>') symbol FROM source_lines l CROSS JOIN line_patterns p WHERE rx_matches(l.text,p.pattern) AND NOT rx_matches(l.text,'^\\s*#') AND NOT rx_matches(l.__path,'^conform/|(?:^|/)(?:tests|test_[^/]*)/') AND NOT rx_matches(l.__path,'(?:^|/)test_[^/]*$') AND NOT EXISTS(SELECT 1 FROM nodes s WHERE s.__path=l.__path AND s.kind IN ('string','concatenated_string') AND s.line<=l.line AND l.line<=s.line+length(s.text)-length(replace(s.text,char(10),'')) AND instr(s.text,char(10))>0 AND NOT rx_matches(s.text,'^[rRuUbB]*[fF]'))"),
      S('direct_patterns',"SELECT l.__path,l.__start,l.__end,l.issue,l.__start||':'||l.issue identity FROM direct_sites l WHERE NOT (l.__path IN ('l2055_lazy_result/lazy_result.py','l2055_lazy_result/lazy_seq.py') AND (l.symbol IN "+vals('LOCKED_PUBLIC_LAZY_FACADE_SYMBOLS')+" OR rx_matches(l.symbol,"+prefixes('LOCKED_PUBLIC_LAZY_FACADE_SYMBOL_PREFIXES')+"))) AND NOT(l.__path='l2070_batching/server_ref.py' AND l.issue IN "+vals('SERVER_REF_CORE_SLOT_PATTERN_NAMES')+") AND NOT(l.issue='.resolve()' AND rx_matches(l.symbol,"+prefixes('NON_LAZY_RESOLVE_SYMBOL_PREFIXES')+")) AND NOT(l.issue='.result()' AND l.symbol IN "+vals('NON_LAZY_RESULT_SYMBOLS')+") AND NOT(l.issue IN ('.resolve()','.resolve_async()','.result()') AND l.symbol IN (SELECT symbol FROM approved_external)) AND NOT(l.issue='.resolve()' AND instr(l.text,'ResolveVersionedForeignKeyTargetIntent(')>0)")
    ])
    full="SELECT * FROM transitive_patterns UNION ALL SELECT * FROM phase_patterns UNION ALL SELECT * FROM external_definitions UNION ALL SELECT * FROM preprocess_patterns UNION ALL SELECT * FROM direct_patterns"
    item=clause('eager-resolution',stages,full,{'source_lines':raw,'strings':E(A(O(K('string'),K('concatenated_string')),P('STRING'),{'regex':r'''(?i)^[ru]*["']'''}),{'value':'capture.DECODED.text'},transform={'DECODED':{'substring':{'source':'$STRING','value':True,'startChar':0}}})})
    base=lambda relation:'SELECT __path path,__start start_byte,__end end_byte,issue,identity FROM '+relation
    item['relational']['query']={'$option':'entryPoint','cases':{'_scan_transitive_eager_ast':base('transitive_patterns'),'_scan_lower_compile_ast':base('phase_patterns')+" WHERE issue GLOB 'lower:*' OR issue GLOB 'compile:*'",'_scan_preprocess_ast':base('preprocess_patterns'),'_scan_external_io_boundary_definition_ast':base('external_definitions'),'_scan_legacy_boundary_definition_ast':base('external_definitions')+' WHERE 0'},'default':base('transitive_patterns')+' UNION ALL '+base('phase_patterns')+' UNION ALL '+base('external_definitions')+' UNION ALL '+base('preprocess_patterns')+' UNION ALL '+base('direct_patterns')}
    strings=item['relational']['inputs']['raw_strings']['evidence']['query']['ast']['rule']
    strings['all'].append(O({'inside':{'kind':'call','has':{'field':'function','any':[{'kind':'identifier','regex':'^(getattr|hasattr)$'},{'kind':'attribute','has':{'field':'attribute','regex':'^(__getattribute__|getattr_static)$'}}]},'stopBy':'end'}},{'inside':{'kind':'subscript','stopBy':'neighbor'}}))
    p['clauses'].append(item);return p
